use std::str::FromStr;

#[derive(Debug)]
struct CallNumber {
    shelf: String,
    slot: u32,
}

impl FromStr for CallNumber {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.split_once('-') {
            Some((shelf, slot)) => match slot.parse::<u32>() {
                Ok(n) => Ok(CallNumber { shelf: shelf.to_string(), slot: n }),
                Err(_) => Err(format!("bad slot number in {s:?}")),
            },
            None => Err(format!("no dash in {s:?}")),
        }
    }
}

fn main() {
    let a: CallNumber = "QA-76".parse().unwrap();
    println!("shelf {}, slot {}", a.shelf, a.slot);
    println!("{:?}", "PR-4034".parse::<CallNumber>());
    println!("{:?}", "QA76".parse::<CallNumber>());
    println!("{:?}", "QA-seven".parse::<CallNumber>());
}

