use std::ops::{Add, Mul, Neg};

#[derive(Debug, Clone, Copy, PartialEq)]
struct Step {
    x: i32,
    y: i32,
}

impl Add for Step {
    type Output = Step;
    fn add(self, other: Step) -> Step {
        Step { x: self.x + other.x, y: self.y + other.y }
    }
}

impl Mul<i32> for Step {
    type Output = Step;
    fn mul(self, times: i32) -> Step {
        Step { x: self.x * times, y: self.y * times }
    }
}

impl Neg for Step {
    type Output = Step;
    fn neg(self) -> Step {
        Step { x: -self.x, y: -self.y }
    }
}

fn main() {
    let east = Step { x: 1, y: 0 };
    let north = Step { x: 0, y: 1 };
    let walk = east + north;
    println!("{walk:?}");
    let far = 3 * walk;
    println!("{far:?}");
    let back = -far;
    println!("{back:?}");
    println!("{}", far + back == Step { x: 0, y: 0 });
}

