use std::fmt;

struct Plain(u32);
struct Padded(u32);

impl fmt::Display for Plain {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "#{}", self.0)
    }
}

impl fmt::Display for Padded {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.pad(&format!("#{}", self.0))
    }
}

fn main() {
    println!("[{:>8}]", Plain(7));
    println!("[{:>8}]", Padded(7));
    println!("[{:<8}]", Padded(42));
}

